// github.js, trimmed
export async function putFile(relPath, contentBase64, message, token) {
  const sha = await getFileSha(relPath, token);        // null when new
  const payload = { message, content: contentBase64, branch: GH.branch };
  if (sha) payload.sha = sha;                           // update vs create
  const res = await fetch(contentsUrl(relPath), {
    method: "PUT",
    headers: headers(token),
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await describeError(res));
  return res.json();
}
